import{PINS}from'./pins.mjs';import{createStreamNight,mixForMinutes}from'./layer.mjs';const hash=async b=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',b))].map(x=>x.toString(16).padStart(2,'0')).join('');export async function loadStreamNight({fetcher=fetch,signal,image,actors,sourceOrigin=[984,1298],canvasFactory=(w,h)=>new OffscreenCanvas(w,h)}){let dead=false,layer=null;const own=[],check=()=>{if(dead||signal?.aborted)throw Error('STREAM_NIGHT_CANCELLED')};try{const bank={};for(const[p,pin]of Object.entries(PINS)){check();const r=await fetcher(new URL(p,import.meta.url),{signal});if(!r.ok)throw Error('STREAM_NIGHT_MISSING');const b=new Uint8Array(await r.arrayBuffer());check();if(b.length!==pin.bytes||await hash(b)!==pin.sha256)throw Error('STREAM_NIGHT_PIN');bank[p]=b}const copy=b=>b.buffer.slice(b.byteOffset,b.byteOffset+b.byteLength),depthAlpha=bank['assets/lamp14-alpha.u8'];layer=createStreamNight({ids:new Uint32Array(copy(bank['assets/lamp14-ids.u32'])),glass:bank['assets/lamp14-glass.u8'],ground:new Float32Array(copy(bank['assets/lamp14-ground.f32'])),depthAlpha});const c=canvasFactory(90,183);own.push(c);const cg=c.getContext('2d');cg.drawImage(image,1440-sourceOrigin[0],1400-sourceOrigin[1],90,183,0,0,90,183);let current=cg.getImageData(0,0,90,183).data;c.width=c.height=1;own.pop();const alphas=new Map();for(const[id,frame]of Object.entries(actors)){const c=canvasFactory(107,107);own.push(c);const g=c.getContext('2d');g.drawImage(frame.image??frame,0,0);const p=g.getImageData(0,0,107,107).data;alphas.set(id,Uint8Array.from({length:11449},(_,i)=>p[i*4+3]));c.width=c.height=1;own.pop()}check();return{depth(ctx,camera,foot){check();if(foot[1]>=1575||camera[0]>=1530||camera[0]+960<=1440||camera[1]>=1583||camera[1]+540<=1400)return;const x=1440-camera[0],y=1400-camera[1],im=ctx.getImageData(x,y,90,183);for(let p=0;p<16470;p++){const a=depthAlpha[p]/255;if(a)for(let c=0;c<3;c++)im.data[p*4+c]=Math.round(current[p*4+c]*a+im.data[p*4+c]*(1-a))}ctx.putImageData(im,x,y)},apply(ctx,camera,{foot,frame,minutes=720,lights=true,rest=false}){check();if(rest||mixForMinutes(minutes)===0)return{mix:0,rows:0};const im=ctx.getImageData(0,0,960,540),r=layer.apply(im.data,camera,{foot,minutes,lights,rest,actorAlpha:alphas.get('actor:'+frame),actorOrigin:[foot[0]-camera[0]-53,foot[1]-camera[1]-90]});ctx.putImageData(im,0,0);return r},dispose(){if(dead)return;dead=true;layer.dispose();alphas.clear();current=null}}}catch(e){dead=true;layer?.dispose();for(const c of own)c.width=c.height=1;throw e}}
